-- Asterwell Health & Services Ltd (FICTIONAL, synthetic data for portfolio practice)
-- SQL Server script: creates the Asterwell database and loads 6 tables.
-- How to run: open in SSMS and press F5 (Execute). Takes about 1 minute.

IF DB_ID('Asterwell') IS NULL CREATE DATABASE Asterwell;
GO
USE Asterwell;
GO
SET NOCOUNT ON;
GO
DROP TABLE IF EXISTS clinics;
CREATE TABLE clinics (Clinic_ID VARCHAR(5) PRIMARY KEY, Clinic_Name VARCHAR(50), Region VARCHAR(30), Opening_Year INT, Monthly_Capacity INT);
GO
GO
DROP TABLE IF EXISTS services;
CREATE TABLE services (Service_ID VARCHAR(5) PRIMARY KEY, Service_Name VARCHAR(50), Category VARCHAR(30), Standard_Price DECIMAL(10,2));
GO
GO
DROP TABLE IF EXISTS patients;
CREATE TABLE patients (Patient_ID VARCHAR(10) PRIMARY KEY, Gender VARCHAR(10), Postcode_Area VARCHAR(5), Registration_Date DATE);
GO
GO
GO
GO
GO
GO
GO
GO
GO
DROP TABLE IF EXISTS appointments;
CREATE TABLE appointments (Appointment_ID VARCHAR(12) PRIMARY KEY, Patient_ID VARCHAR(10), Clinic_ID VARCHAR(5) NULL, Service_ID VARCHAR(5), Appointment_Date DATE, Booking_Date DATE, Appointment_Type VARCHAR(20), Status VARCHAR(20), Waiting_Days INT, Patient_Age_Band VARCHAR(10), Referral_Source VARCHAR(30));
GO
GO
GO
GO
GO
GO
GO
GO
GO
GO
GO
GO
GO
GO
GO
GO
DROP TABLE IF EXISTS employees;
CREATE TABLE employees (Employee_ID VARCHAR(8) PRIMARY KEY, Clinic_ID VARCHAR(5), Department VARCHAR(30), Job_Role VARCHAR(40), Start_Date DATE, Leave_Date DATE NULL, Annual_Salary INT);
GO
GO
DROP TABLE IF EXISTS transactions;
CREATE TABLE transactions (Transaction_ID VARCHAR(8) PRIMARY KEY, Patient_ID VARCHAR(10), Service_ID VARCHAR(5), Transaction_Date DATE, Amount DECIMAL(10,2), Payment_Method VARCHAR(20));
GO
GO
GO
GO
GO
GO
GO
GO

-- Check: row counts (should be 12, 8, 7468, 14480, 420, 6500)
SELECT 'clinics' AS table_name, COUNT(*) AS row_count FROM clinics
UNION ALL SELECT 'services', COUNT(*) FROM services
UNION ALL SELECT 'patients', COUNT(*) FROM patients
UNION ALL SELECT 'appointments', COUNT(*) FROM appointments
UNION ALL SELECT 'employees', COUNT(*) FROM employees
UNION ALL SELECT 'transactions', COUNT(*) FROM transactions;
GO